import type { FlashcardText, FlashcardCategory } from './types.ts';

// IDs retain the original topic identity. New topics start after the imported bank.
function card(id: number, category: FlashcardCategory, question: string, answer: string, followUp: string, code?: FlashcardText['code']): FlashcardText {
  return { id: `fc-${String(id).padStart(3, '0')}`, category, question, answer, followUp, ...(code ? { code } : {}) };
}
const kotlin = (context: string, code: string): FlashcardText['code'] => ({ language: 'kotlin', context, code });

const reviewedCards: readonly FlashcardText[] = [
  card(1, 'kotlin', 'A UI state exposes a val List, but rows change without a new emission. What went wrong?',
    'A val prevents reassignment; List only exposes read operations. Neither makes the underlying objects immutable. If another owner mutates the same list, observers may see shared changes without a state notification. Expose immutable snapshots, keep mutation private, and replace the affected item and collection when publishing state. Data-class copy is shallow, so nested mutable objects still need deliberate copying.',
    'StateFlow suppresses equal updates. Copying the wrapper after mutating its shared list may still compare equal. For large collections, consider persistent immutable collections rather than repeatedly copying everything.',
    kotlin('Inside a ViewModel; Item is an immutable data class and items is MutableStateFlow<List<Item>>.', 'fun rename(id: String, name: String) {\n    items.update { rows ->\n        rows.map { if (it.id == id) it.copy(name = name) else it }\n    }\n}')),
  card(4, 'kotlin', 'A Java SDK returns nullable platform types. Where would you enforce null safety?',
    'Validate at the SDK boundary and convert platform types into explicit nullable or non-null domain values. Missing optional data should stay optional; missing required data should become a meaningful integration failure. Capture a mutable property in a local val before checking it. Avoid spreading !! across the UI, because Kotlin cannot guarantee the nullability of unannotated Java values.',
    'Annotations improve interop but do not validate remote payloads. Distinguish malformed data from a legitimate empty result; log safe context rather than sensitive payloads. Use requireNotNull for caller preconditions and explicit domain failures for expected bad input.'),
  card(11, 'kotlin', 'How would you model loading, content, and failure without impossible UI combinations?',
    'Use an immutable state model with only valid combinations. A sealed hierarchy fits mutually exclusive initial states and gives exhaustive when handling. A data class often works better for existing content plus refresh progress and a recoverable error. Keep transport exceptions out of rendering and model the user action the state allows.',
    'A separate boolean for every condition can permit loading, empty, and fatal error together. Conversely, a single Loading subtype can accidentally erase cached content during refresh.',
    kotlin('Screen-level state; actual content can carry domain models.', 'sealed interface FeedState {\n    data object Loading : FeedState\n    data class Content(val titles: List<String>) : FeedState\n    data class Failed(val canRetry: Boolean) : FeedState\n}')),
  card(15, 'kotlin', 'A Kotlin extension behaves differently when a value is typed as an interface. Why?',
    'Extensions resolve using the compile-time receiver type; they are not virtual members. An extension on a concrete implementation will not be selected through an interface reference just because the runtime object has that implementation. Put polymorphic behavior on the interface, or delegate to an injected strategy, and reserve extensions for discoverable helpers.',
    'A real member takes precedence over an applicable extension. Avoid public extensions whose names hide domain behavior or imply that they can access private implementation state.'),
  card(24, 'kotlin', 'Why can a generic JSON helper not reliably check that a value is List<User> at runtime?',
    'JVM generic arguments are mostly erased, so an is check can establish List<*> but cannot verify every element is a User. An inline reified parameter preserves the call-site type for supported operations, but an is T check alone still cannot deeply validate nested generic contents. Use the serialization library’s typed serializer or type token, then validate domain constraints.',
    'Unchecked casts postpone failure to an unrelated access. Reified helpers can simplify APIs, but they are not a replacement for schema validation or handling unknown fields and incompatible payloads.'),
  card(27, 'kotlin', 'Would you switch a large mapping pipeline to Sequence to improve scrolling?',
    'Measure the hot path first. Sequence lazily chains work and can avoid intermediate collections, particularly when filtering and taking only a small prefix. Small pipelines can be faster as eager collections because lazy iteration adds overhead. Neither approach moves CPU work off the main thread; expensive transformations belong in a main-safe data or presentation operation.',
    'Use a benchmark with realistic data and allocations. Cache reusable transformations, avoid doing them on every composition, and consider indexed database queries before optimizing an unnecessarily large in-memory scan.'),
  card(35, 'kotlin', 'How would you evolve a Kotlin API still called by Java screens?',
    'Keep Java callers in the compatibility check. Use explicit nullability contracts, deliberate JVM overloads or static entry points where needed, and Java-friendly callback or future boundaries for suspend APIs. Kotlin default arguments and suspend signatures are not automatically ergonomic Java APIs. Migrate behind a narrow adapter instead of rewriting all callers at once.',
    'JvmOverloads can expand the public API and overload ambiguity. Check binary as well as source compatibility for published libraries; add Java call-site tests for the signatures the app actually uses.'),
  card(37, 'coroutines', 'A suspend repository method still freezes the UI. How would you fix it?',
    'Suspend does not select a background thread. Inspect the method for blocking disk, legacy network calls, or expensive parsing on Main. Make the implementation main-safe by moving blocking I/O to an injected IO dispatcher and CPU work to Default. Truly asynchronous libraries often already handle threading; wrapping every suspend call in IO adds noise.',
    'Inject dispatchers for deterministic tests. A Service also runs callbacks on the main thread by default; changing the component does not fix blocking work.',
    kotlin('LegacyStore.readText is blocking; imports: CoroutineDispatcher and withContext.', 'class NotesRepository(\n    private val store: LegacyStore,\n    private val io: CoroutineDispatcher,\n) {\n    suspend fun read(): String = withContext(io) { store.readText() }\n}')),
  card(38, 'coroutines', 'A dashboard needs two required API results. How would you load them concurrently?',
    'Use async children inside coroutineScope and await both. The caller owns the lifetime, the scope waits for the children, and one required child failing cancels its sibling. Catch the failure at the operation boundary and produce one coherent screen outcome. Use sequential calls when one result depends on the other.',
    'Async is useful for parallel results; withContext is clearer for a sequential context switch. Bound fan-out so a large list of requests does not overload the server or device.',
    kotlin('Inside a repository; api methods suspend, Dashboard takes Profile and List<Alert>. Imports: async, coroutineScope.', 'suspend fun loadDashboard(): Dashboard = coroutineScope {\n    val profile = async { api.profile() }\n    val alerts = async { api.alerts() }\n    Dashboard(profile.await(), alerts.await())\n}')),
  card(46, 'coroutines', 'One optional dashboard panel fails. How can other panels keep loading?',
    'Use supervisorScope for independent children and handle each expected failure deliberately. Supervision prevents a child failure from cancelling siblings; it does not turn exceptions into values or prevent an unhandled launch exception from crashing. With async, observe every Deferred and map optional failures to a panel-level outcome while preserving cancellation.',
    'An exception thrown by the supervisorScope block itself still cancels its children. Avoid catching an await failure outside a supervisor block if you intend siblings to continue. Use ordinary coroutineScope for all-or-nothing work.'),
  card(51, 'coroutines', 'A cancelled search keeps consuming CPU or reports an error. What would you inspect?',
    'Cancellation is cooperative. Check CPU loops for ensureActive or yield, and check broad catch blocks and runCatching for swallowed CancellationException. Rethrow cancellation before converting expected failures into UI errors. Cancel or unregister underlying callback work too; cancelling a coroutine cannot automatically stop every blocking library call.',
    'Use a tiny NonCancellable cleanup block only when suspending cleanup is essential. It is not a way to keep obsolete business work alive.',
    kotlin('Inside a coroutine; imports: CancellationException, IOException, currentCoroutineContext, ensureActive.', 'try {\n    currentCoroutineContext().ensureActive()\n    repository.refresh()\n} catch (cancelled: CancellationException) {\n    throw cancelled\n} catch (offline: IOException) {\n    showRetry()\n}')),
  card(57, 'coroutines', 'Which scope should own a request when the user rotates or leaves a screen?',
    'Use viewModelScope for screen work that should survive configuration changes and stop when the ViewModel is cleared. Use a lifecycle or composition scope for work tied to that UI instance. Use an injected application scope only for explicitly process-owned work. None of these survives process death; persist intent and use an appropriate scheduler when completion must be recoverable.',
    'GlobalScope hides ownership. A ViewModel on a navigation back stack can remain alive while invisible, so visibility-sensitive collection needs lifecycle control rather than relying only on ViewModel clearing.'),
  card(59, 'coroutines', 'A Fragment keeps collecting data after its view is destroyed. How would you fix it?',
    'Launch collection in viewLifecycleOwner.lifecycleScope and repeatOnLifecycle at STARTED. The block cancels below STARTED and restarts on return, while the outer job ends with that view. The Fragment instance can outlive its view, so observing with the Fragment lifecycle can retain a stale binding. Launch parallel collectors as separate children inside the repeat block.',
    'In Compose, prefer collectAsStateWithLifecycle for UI state. Clear view binding in onDestroyView. Restarting collection can restart a cold producer, so share expensive upstream work at the correct owner.',
    kotlin('In Fragment.onViewCreated; render uses only the current view. Imports: lifecycleScope, repeatOnLifecycle, Lifecycle, launch.', 'viewLifecycleOwner.lifecycleScope.launch {\n    viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {\n        viewModel.state.collect { render(it) }\n    }\n}')),
  card(61, 'coroutines', 'Two coroutines update the same cache and occasionally lose writes. What would you change?',
    'Identify the invariant and give mutation one owner. For a single StateFlow value, update performs an atomic transformation; for multiple related values, serialize operations or use Mutex around a short critical section. Use a database transaction for durable multi-row invariants. Switching both callers to IO does not make compound operations atomic.',
    'StateFlow update may retry its lambda, so keep it free of side effects. Mutex is not reentrant. Do not hold a JVM monitor across suspension; avoid holding any lock during slow network work.'),
  card(64, 'coroutines', 'How would you safely wrap a one-shot Android callback API as a suspend function?',
    'Use suspendCancellableCoroutine and define success, failure, and cancellation together. Resume the continuation exactly once, propagate errors, and cancel the underlying request or unregister its listener when the caller cancels. Account for cancellation racing with completion; resource-returning APIs may need a resume cancellation handler so delivered resources are closed.',
    'An isActive check alone does not prevent two callbacks racing to resume. Rely on a documented one-shot contract or use a race-safe completion gate. Use callbackFlow for repeated events.'),
  card(65, 'coroutines', 'How would you test debounce, retries, and cancellation without waiting in real time?',
    'Use runTest and test dispatchers sharing one TestCoroutineScheduler. Inject dispatchers and collaborators so delays run on virtual time. Start collection before triggering a hot flow, advance time deliberately, and assert observable state and cancellation. Use backgroundScope for a collector that intentionally never completes.',
    'runTest cannot skip delays on a hard-coded real dispatcher. advanceTimeBy does not execute tasks scheduled exactly at its new boundary until runCurrent; avoid arbitrary sleeps and assert failures as well as success.'),
  card(68, 'flow', 'A Flow transformation does expensive parsing. Where should flowOn go?',
    'flowOn changes upstream execution, while downstream collection stays in the collector’s context. Put it after the CPU-heavy upstream transformation to move that work to an appropriate dispatcher. Do not emit from a different context inside a regular flow builder; preserve Flow context invariants or use operators designed for concurrency.',
    'Moving a repository’s upstream work does not move an expensive UI collector. Room and networking libraries may already provide main-safe APIs. Measure context switches and keep dispatcher ownership explicit.'),
  card(69, 'flow', 'A Flow error handler misses a rendering exception. Why, and where should retries live?',
    'catch only handles exceptions upstream of its position. Failures in a downstream collector need handling at that boundary. Place retryWhen before mapping a terminal upstream failure to state, retry only transient failures with bounds and backoff, and let cancellation propagate. A retry recollects upstream, so side effects may run again.',
    'Do not retry authentication failures forever or re-execute a non-idempotent write blindly. A fallback emission completes that collection unless the flow itself continues producing; design a user retry trigger for recovery.'),
  card(73, 'flow', 'When would you use StateFlow instead of SharedFlow for UI state?',
    'Use StateFlow when a returning collector must immediately render a current value. It requires an initial value and conflates equal updates. SharedFlow is useful for broadcasts with explicit replay and buffer choices, but a replay-zero emission with no subscribers is lost. Model important outcomes as state with acknowledgement when losing or replaying them would break the user journey.',
    'Neither flow guarantees exactly-once delivery across process death. Keep mutable flows private, publish read-only views, and avoid representing navigation or payment completion as an unbuffered fire-and-forget event.',
    kotlin('Inside a ViewModel; imports: MutableStateFlow, asStateFlow.', 'private val _state = MutableStateFlow<FeedState>(FeedState.Loading)\nval state = _state.asStateFlow()')),
  card(74, 'flow', 'Two collectors trigger duplicate API requests. How would you share a cold stream?',
    'Use stateIn for current state or shareIn for shared emissions in an explicitly owned scope. Select WhileSubscribed when upstream should follow subscribers, often with a short stop timeout to bridge rotation. Choose an initial state and decide whether cached replay should remain when upstream stops. Sharing avoids duplicate producers but does not make expensive work durable.',
    'An eagerly started stream spends resources with no UI. A stopped upstream restarts on a later subscription; handle errors before sharing and make refresh semantics explicit.',
    kotlin('Inside a ViewModel; repository.observeFeed returns Flow<List<Item>>. Imports: stateIn, SharingStarted.', 'val items = repository.observeFeed().stateIn(\n    scope = viewModelScope,\n    started = SharingStarted.WhileSubscribed(5_000),\n    initialValue = emptyList(),\n)')),
  card(76, 'flow', 'A screen combines a filter and cached rows. Would you use combine or zip?',
    'Use combine so either input updates the result using the latest value from each, after both have emitted. Zip pairs emissions one-for-one and can stall while waiting for a matching value, which usually does not fit independent UI state. Keep the transformation pure and move expensive filtering off Main or into the database.',
    'Combine does not provide an atomic snapshot of independently updated flows. If two fields must change together, publish one state object or derive them from one transactional source.'),
  card(78, 'flow', 'How would you stop stale search results from replacing results for a newer query?',
    'Normalize queries, debounce typing, remove consecutive duplicates, and use flatMapLatest so a new query cancels the previous inner result stream. Place error handling inside the query stream if future queries must remain usable. Check that the underlying API cooperates with cancellation; use request identity checks at non-cooperative boundaries.',
    'Debounce trades latency for fewer requests. flatMapLatest suits replaceable reads; it is unsafe for writes that must all finish. Concat preserves order, while merge allows bounded independent concurrency.'),
  card(80, 'flow', 'A slow collector cannot keep up with location updates. Should you buffer, conflate, or use collectLatest?',
    'Choose based on what may be dropped. Buffer queues emissions up to a capacity and then applies its overflow policy. Conflate keeps the latest pending value when intermediate states do not matter. collectLatest cancels the previous processing block, which only works if that work can be safely abandoned. Every option needs an explicit latency and loss policy.',
    'Do not conflate accounting events or cancel partially committed writes. For location display the latest point may suffice; for a recorded route, persist samples durably and decouple display from ingestion.'),
  card(81, 'flow', 'How would you expose a repeated SDK listener as Flow without leaking the listener?',
    'Use callbackFlow, register the listener for the collection lifetime, send events with trySend, and unregister in awaitClose. Define what happens when the channel is full or closed. A cold callbackFlow registers once per collector; share it at the right owner when only one SDK subscription is intended.',
    'Callbacks and cleanup may race, so registration and removal must respect the SDK’s threading contract. Ignoring trySend failure can silently lose important events; choose capacity or durable storage based on the data.'),
  card(85, 'framework', 'A singleton retains an Activity after rotation. How would you choose and manage its Context?',
    'Inspect why the singleton needs a Context. App-scoped storage and services usually use applicationContext; UI work needs a current themed Activity and should stay with its lifecycle owner. Remove long-lived Activity references and unregister listeners or callbacks. An Activity reference in a singleton prevents its entire view tree from being collected.',
    'Replacing every Context with applicationContext can break dialogs and themed resources. Weak references do not fix missing ownership or cleanup; pass short-lived UI dependencies only for the duration of an operation.'),
  card(92, 'framework', 'A checkout survives rotation but loses its draft after process death. How would you restore it?',
    'ViewModel retains screen state across configuration recreation but not process death. Put small reconstruction inputs such as an item ID or text draft in SavedStateHandle or saved UI state, and durable checkout data in a repository backed by storage. Restore from these inputs and reconcile with the server instead of persisting an entire object graph in a Bundle.',
    'Saved state is a restoration aid, not guaranteed durable storage after every termination or task dismissal. Do not depend on onDestroy to save; persist important edits as they happen and test real restoration paths.'),
  card(96, 'framework', 'How would you maintain Fragment-based screens while incrementally migrating to Compose?',
    'Respect both the Fragment and its shorter view lifecycle. Keep restorable inputs in arguments or a saved-state owner, keep screen state in the correctly scoped ViewModel, and dispose composition with the view lifecycle. Establish one state owner across the old and new UI so callbacks do not create two competing models.',
    'Use a FragmentFactory deliberately for constructor injection rather than assuming custom constructors survive framework recreation. Clear bindings and listeners in onDestroyView and test back-stack recreation, rotation, and process restoration.'),
  card(99, 'framework', 'A deep link opens a duplicate screen and Back exits unexpectedly. How would you debug it?',
    'Inspect the task stack, manifest launch modes, intent flags, and how both cold and warm starts consume the incoming intent. Define the intended parent journey, authenticate before showing protected content, and route a validated stable ID through one navigation owner. Prefer ordinary task semantics unless the product requires a special launch mode.',
    'Test notification taps, verified App Links, existing tasks, and repeated links. App Link verification identifies a domain association; it does not authorize access to the requested record.'),
  card(105, 'framework', 'How would you migrate delayed Handler callbacks without introducing lifecycle bugs?',
    'Identify the callback’s actual owner and threading requirement. A lifecycle-owned coroutine with delay can replace UI timers and cancel when that owner ends; retain Handler when integrating with an API that requires a particular Looper. Remove posted callbacks when their owner is destroyed and avoid capturing old views or Activities.',
    'A coroutine delay is not an exact alarm or durable schedule. Handler and Looper remain relevant for message-queue debugging and legacy integration; replacing syntax alone does not establish correct ownership.'),
  card(109, 'framework', 'A bound-service call intermittently stalls the UI. What would you investigate?',
    'Binder calls can be synchronous, so a main-thread IPC call may wait on another process, its locks, or disk access. Inspect both sides of a trace, move blocking client work off Main when the API permits it, and make server work bounded. Handle remote process death and reconnection explicitly, and keep parcels small.',
    'AIDL exposes an API boundary, not automatic authorization or thread safety. Server callbacks can arrive on Binder threads; marshal UI changes to Main and avoid locks across remote calls.'),
  card(112, 'framework', 'A user revokes permission while a feature is open. How should the app respond?',
    'Treat permission as revocable capability, not a one-time onboarding flag. Check immediately before protected operations, handle SecurityException where revocation can race, stop or release resources safely, and show an actionable fallback. Ask in context and distinguish temporary denial from a flow that needs system settings.',
    'Avoid repeatedly prompting or blocking unrelated features. Test denial, revocation, process recreation, and the permissions needed by the app’s supported Android versions and target SDK.'),
  card(120, 'compose', 'Where would you own state for a reusable form and a screen that saves it?',
    'Hoist state to the lowest owner shared by its readers and writers. A reusable form accepts values and callbacks; the screen owner coordinates validation and saving. Keep purely local UI state close to the component, and put business state in a ViewModel or repository. State goes down and user actions go up.',
    'Hoisting everything to a global ViewModel couples unrelated components. Remember caches within composition; rememberSaveable can restore small supported UI values, while durable drafts need persistent storage.'),
  card(123, 'compose', 'An unstable parameter appears in a Compose compiler report. Would you add @Stable?',
    'First measure whether the affected call causes a real performance problem. Strong skipping allows many composables with unstable parameters to skip using reference identity, while stable parameters use equality. An annotation is a contract about equality and observable mutation, not a performance switch. Prefer honest immutable models and observable state before considering annotations.',
    'A mutable object marked Stable without notifying changes can produce stale UI. Lists can be inferred unstable even when used immutably; compare release benchmarks and compiler reports for the actual toolchain.'),
  card(125, 'compose', 'After reordering a LazyColumn, expanded row state moves to the wrong item. Why?',
    'Positional identity associates remembered state with a position. Supply stable, unique item keys so identity follows the domain item across insertions and moves. Use a saveable key type when item state must restore through Android saved state. Keep expensive row work outside composition and use contentType when different row layouts can be reused.',
    'Index keys are unsafe for reorderable data; changing keys on each refresh destroys identity. A key does not make an ordinary mutable list observable.',
    kotlin('Inside a composable; Item has a stable String id and ItemRow is a composable.', 'LazyColumn {\n    items(items = rows, key = { it.id }) { item ->\n        ItemRow(item)\n    }\n}')),
  card(126, 'compose', 'A request restarts on every recomposition, or uses an old callback. How would you fix its effect?',
    'Do not launch effects directly in the composable body. LaunchedEffect starts composition-owned suspend work and restarts when its keys change. Include inputs whose change invalidates the work; use rememberUpdatedState for a changing callback that should not restart it. Use DisposableEffect for listener registration with synchronous cleanup.',
    'A constant key is appropriate only for work whose lifetime really is that composition location. User-click jobs can use rememberCoroutineScope; durable business work should be owned outside composition.'),
  card(131, 'compose', 'A scroll-to-top button recomposes on every scroll tick. How would you reduce that work?',
    'Use derivedStateOf when the UI needs a coarse result, such as whether the first visible item is past a threshold, that changes less often than its inputs. Keep the derived state remembered and read that result at the relevant scope. Use snapshotFlow for flow-based observation and effects rather than rendering.',
    'Derived state adds overhead and is unnecessary for cheap values that change as often as their inputs. Do not key remember with the rapidly changing value, which would rebuild the derived state on every update.',
    kotlin('Inside a composable; listState is rememberLazyListState(). Imports: remember, derivedStateOf and getValue.', 'val showTop by remember(listState) {\n    derivedStateOf { listState.firstVisibleItemIndex > 0 }\n}')),
  card(133, 'compose', 'How would you collect a ViewModel StateFlow without keeping an invisible Android screen active?',
    'Use collectAsStateWithLifecycle to expose lifecycle-aware Compose state and render it. Keep the mutable StateFlow private to the ViewModel and share expensive upstream work there with a deliberate policy. The collector normally stops below STARTED; that stops a producer only if its sharing and ownership policy allow it.',
    'CollectAsState alone follows composition rather than Android visibility. Do not collect in an unkeyed coroutine launched during rendering. Use an explicit lifecycle effect for non-rendering side effects.'),
  card(137, 'compose', 'How would you diagnose and reduce unnecessary recomposition in a janky screen?',
    'Reproduce the slow journey in a release-like build, inspect frame traces, and use recomposition and compiler tooling to locate costly work. Distinguish composition from layout, drawing, image loading, and I/O. Narrow state reads, keep models immutable, supply list keys, and defer rapidly changing reads to later phases when semantics permit. Verify improvements with a representative benchmark.',
    'A high recomposition count is not proof of slow frames. Do not scatter remember or stability annotations without measuring; they can hide incorrect state or retain data longer than intended.'),
  card(138, 'compose', 'How would you embed Compose in a Fragment and a legacy View inside Compose?',
    'Use ComposeView for Compose within a View hierarchy and AndroidView for a View within composition. In a Fragment, tie the composition to the view lifecycle. Keep creation in AndroidView’s factory and apply current state in update; release listeners and resources at the appropriate disposal boundary. Route callbacks to one state owner.',
    'Avoid recreating expensive Views for every state change or retaining a destroyed Fragment binding. Test focus, accessibility, nested scrolling, and lifecycle restoration during incremental migration.'),
  card(139, 'compose', 'A custom Compose control looks correct but is hard to test or use with TalkBack. What would you change?',
    'Expose meaningful semantics: role, label, current state, and supported actions. Prefer standard accessible components and sensible touch targets. Merge or clear descendant semantics only when it matches the control’s meaning, and use null contentDescription for purely decorative images. Tests should exercise the resulting user-facing semantics.',
    'A test tag does not make a control accessible. Avoid duplicate spoken labels, localize descriptions, and verify large fonts, keyboard focus, and TalkBack behavior.'),
  card(146, 'architecture', 'How would you structure a screen that shows cached data and refreshes from an API?',
    'The UI renders immutable ViewModel state and sends actions. The ViewModel observes a repository and triggers refresh; the repository coordinates API and local storage. Make the database the authoritative read source: network responses update it and the observed query updates the UI. Represent refresh and recoverable errors separately so cached content stays visible.',
    'Clean Architecture keeps stable business policy independent of transport and storage details; add a domain use case when policy is complex or shared. Avoid two competing lists from network and database, and avoid a layer that merely forwards every call.'),
  card(147, "architecture", "When should a domain layer be added?",
    "When business logic is complex or reused across multiple ViewModels or entry points. Adding one use-case class for every trivial repository call creates ceremony without useful separation.",
    'Use a use case for shared checkout validation or sync policy; keep a trivial settings lookup direct. Dependencies should point toward stable policy, with storage and networking behind replaceable boundaries.'),
  card(152, 'architecture', 'How would you scope and replace dependencies for a Hilt-backed screen?',
    'Inject dependencies through constructors, bind interfaces in modules where needed, and use qualifiers for distinct implementations of the same type. Match scopes to owners: a process-wide repository may be singleton, while screen state belongs to its ViewModel. Replace modules or provide fakes in tests rather than having production code detect test mode.',
    'Do not let a singleton capture an Activity-scoped dependency. A scope controls instance sharing and lifetime; it does not make mutable state thread-safe or justify making every object a singleton.'),
  card(153, "architecture", "What is the danger of an incorrectly scoped dependency?",
    "It may retain shorter-lived objects and leak them, or share mutable state more broadly than intended. Scope should match the actual owner and lifetime.",
    'For example, a singleton image helper retaining an Activity can leak it after rotation. Inspect the dependency path and fix the owner; a weak reference is not a general replacement for a correct lifetime.'),
  card(154, 'architecture', 'When would you split a growing Android app into modules?',
    'Start with measured build bottlenecks, clear feature ownership, or boundaries that need enforcement. Put stable contracts where dependents can consume them without depending on implementation details. Avoid cyclic dependencies and keep navigation integration explicit. Track incremental build time and team change friction to check whether the split helps.',
    'One module per class adds Gradle overhead. A shared module can become a dumping ground; make its public API small and avoid leaking framework or feature-specific models across every boundary.'),
  card(155, 'architecture', 'How would you synchronize offline edits when the same record changes on another device?',
    'Persist the local edit and an outbox operation atomically, show pending status, and sync durable work when possible. Send a stable operation ID for deduplication and a server version for optimistic concurrency. On conflict, apply a product-defined merge, explicit user resolution, or a documented winner policy, then reconcile the local authoritative view.',
    'Device clocks are unreliable for last-write-wins. Plan deletes with tombstones, account isolation, logout cleanup, and retries after a crash between server commit and local acknowledgement. WorkManager scheduling alone does not solve conflicts.'),
  card(159, 'architecture', 'A Room schema change must preserve millions of users’ offline drafts. How would you ship it?',
    'Define a data-preserving migration for each supported upgrade path, export schemas, and test historical databases with realistic constraints and data. Use auto migrations only for changes they can express; write explicit transformations for semantic changes. Verify queries and indexes after migration, and observe rollout health before expanding release exposure.',
    'Destructive fallback is acceptable only for data that can safely be discarded and rebuilt. Large migrations can slow startup; test realistic database sizes and retain rollback and recovery options.'),
  card(160, 'architecture', 'When should a Room refresh or local mutation use a transaction?',
    'Use a transaction when related rows or metadata must change atomically, such as replacing cached items with their remote pagination keys or saving an edit with its outbox entry. Fetch network data outside the transaction, then commit a short database-only operation. Observe database queries for the resulting consistent state.',
    'Transactions do not make a network request and database write atomic together. A Room observable query may rerun on table invalidation even if its result is equal; use distinctUntilChanged when meaningful downstream work should be suppressed.'),
  card(162, 'architecture', 'Where would you store a theme preference, searchable cached records, and downloaded media?',
    'Use DataStore for small preference or typed settings with asynchronous transactional updates, Room for structured records requiring queries and relational consistency, and files for large opaque or streamed content. Keep file metadata and ownership explicit. Pick storage based on durability, query, size, and consistency requirements.',
    'When migrating SharedPreferences, use a supported migration path and avoid keeping two active writers. DataStore is not a relational database, and neither it nor Room automatically establishes a secure key-management policy.'),
  card(165, 'architecture', 'How should a REST client distinguish errors and decide what the UI can retry?',
    'Separate connectivity and timeout failures, HTTP status failures, authentication expiry, invalid payloads, and domain rejection when behavior differs. Map them at the data boundary into actionable outcomes while preserving cancellation. A transient read can retry with bounds and backoff; invalid input should prompt correction, and an expired session should enter a controlled authentication flow.',
    'Use HTTPS with normal certificate validation; never install a permissive trust manager. Pinning needs a rotation and recovery plan. Respect rate limits, avoid raw exception messages, and require idempotency before retrying writes.'),
  card(166, "architecture", "What makes a sync operation safe to retry?",
    "Idempotency or deduplication, stable operation identifiers, transactional local updates, bounded exponential backoff, and a conflict policy. Retrying blindly can duplicate writes or amplify outages.",
    'A crash after server commit but before local acknowledgement is the key test. An idempotency key must remain stable across attempts; generating a fresh key for each retry defeats server deduplication.'),
  card(167, 'background', 'When would you choose WorkManager over a coroutine or foreground service?',
    'Use a lifecycle-owned coroutine for immediate in-process work that can stop with its owner. Use WorkManager for persistent deferrable work with constraints and retries, such as draining an outbox after process recreation. Choose a foreground service only for eligible ongoing user-visible work needing that execution model. Persist progress and make repeated execution safe.',
    'WorkManager does not guarantee exact timing or bypass force-stop, power, quota, or platform restrictions. Foreground services require appropriate types, permissions, notifications, and permitted start conditions; they are not unrestricted background threads.'),
  card(169, 'background', 'A sync Worker fails repeatedly. When should it retry versus fail?',
    'Return success after a durable completed checkpoint, retry for a transient condition with backoff, and failure for a permanent condition that needs intervention. Classify HTTP and domain errors, bound attempts according to product policy, and expose pending or failed status in storage. Cancellation should stop the coroutine instead of being converted into an ordinary failed result.',
    'Connectivity constraints are hints, not proof that the API is reachable. Preserve idempotency and resumable checkpoints; do not repeatedly upload all bytes or hammer an expired session.'),
  card(170, 'background', 'Multiple entry points schedule the same sync. How would you avoid duplicate work?',
    'Use unique work with a stable logical name and a policy chosen for the job. KEEP retains existing unfinished work; REPLACE cancels and replaces it, which is useful only when new work supersedes old work. Chains can sequence dependencies. The worker must still deduplicate operations because scheduling uniqueness is not an exactly-once execution guarantee.',
    'For periodic work, use the periodic policies appropriate to updating an existing schedule. Avoid accidentally cancelling an in-flight upload on every app start; name work by account when account isolation matters.'),
  card(172, 'background', 'How would you schedule a user reminder that needs a specific time?',
    'Separate a user-visible time alarm from deferrable sync. AlarmManager may fit a justified clock or calendar-style reminder; WorkManager is for eventual work rather than exact timing. Use inexact timing if product requirements allow it, and check exact-alarm eligibility and access for supported Android versions. Persist reminder intent and handle reboot and time changes.',
    'Exact-alarm access is restricted and can be revoked. Do not use an exact alarm to evade background limits or perform long work in a receiver; schedule subsequent work through an appropriate API.'),
  card(173, 'background', 'Sync is delayed when a phone is idle. How would you investigate and design around it?',
    'Inspect WorkManager state, constraints, retry history, app standby status, battery restrictions, and platform scheduling in device diagnostics. Doze and standby can defer background execution, so design eventual consistency, durable pending work, and a foreground refresh path. Communicate freshness rather than promising a fixed background interval.',
    'Avoid continuous polling, battery-exemption prompts without a clear need, or high-priority messages for routine refresh. Quotas and restrictions vary by OS and target SDK; test realistic idle and restricted states.'),
  card(176, 'background', 'How would you handle a push that opens a record and triggers a refresh?',
    'Treat the payload as untrusted, keep receiver processing short, and use a record ID rather than sensitive content. Validate the destination, require the current user’s authorization, and refresh authoritative data. Respect notification permission and channels, and schedule durable follow-up when processing exceeds the callback’s lifetime.',
    'Push is not a durable ordered database log: notifications can be delayed, duplicated, or missed. Reconcile on foreground entry and make handlers idempotent. Test warm, cold, logged-out, and revoked-permission paths.'),
  card(178, 'engineering', 'What would you test for a ViewModel that renders cache, refreshes, and handles failure?',
    'Use a controllable fake repository and test dispatchers to assert initial cached content, refresh status, successful replacement, and a recoverable error that preserves cache. Test cancellation and repeated user actions, not private implementation details. Use local tests for presentation policy and device tests for framework-specific behavior such as Room and restoration.',
    'A fake should obey the real contract; add integration tests where a fake could hide SQL or serialization bugs. Avoid mocks that merely repeat every internal call and sleeps that turn timing into the assertion.'),
  card(181, 'engineering', 'An Espresso test passes locally but flakes when background work runs slowly. How would you fix it?',
    'Find the asynchronous boundary that the test does not control. Espresso synchronizes with the main queue and registered idling resources, not every arbitrary network or executor task. Replace external dependencies with deterministic fakes where appropriate or register an idling resource around real work, then assert user-visible outcomes instead of sleeping.',
    'Register synchronization before starting work and always release it on failure. Compose’s test clock controls Compose scheduling, not all external I/O. Keep a small set of device integration tests for real platform behavior.'),
  card(182, 'engineering', 'How would you test a Compose screen’s loading, retry, and accessible content?',
    'Render the screen with explicit state and callbacks, locate controls through semantics, perform user actions, and assert visible outcomes. Drive loading and error state deterministically with a fake at the screen boundary. Use Compose test synchronization and a controlled clock for animation rather than sleeps, and verify accessible labels and roles.',
    'Test the behavior of state hoisting separately from the ViewModel’s business transitions. Test tags can identify otherwise ambiguous nodes but should not replace meaningful semantics or force assertions about internal layout structure.'),
  card(184, 'engineering', 'How would you investigate a memory leak caused by a long-lived reference to an Activity?',
    'Reproduce a repeatable lifecycle transition, then inspect LeakCanary or a heap dump for the retained Activity and its path from a GC root. Find the owner that outlives it, such as a singleton, listener, coroutine, or delayed callback. Fix scope or unregister at the lifecycle boundary, then repeat the scenario and verify retained instances stop accumulating.',
    'Separate unintended retention from large legitimate allocations when investigating an OOM. Do not assume a weak reference fixes the lifecycle contract; inspect bitmap sizes, caches, and repeated navigation too.'),
  card(186, 'engineering', 'Users report ANRs and jank after a release. What evidence would you collect first?',
    'Segment by release, device, OS, and journey. Inspect ANR traces and Perfetto timelines for main-thread I/O, locks, Binder waits, or expensive work, including the thread holding a contended lock. Distinguish long responsiveness stalls from frame-budget misses. Reproduce the dominant pattern, fix the blocking dependency, and verify against real user metrics.',
    'Do not infer one universal ANR timeout or optimize by guesswork. A sampled main-thread stack may show a symptom; inspect related threads and preceding trace events before assigning the cause.'),
  card(187, 'engineering', 'How would you improve cold startup without breaking first-use behavior?',
    'Measure time to initial display and usable content in a release-like build with Macrobenchmark and traces. Remove unnecessary main-thread initialization, defer noncritical SDKs, and make lazy initialization safe when first used. Use Baseline Profiles for representative journeys and verify the delivered artifact on realistic devices.',
    'Deferral can move a stall to the first tap rather than remove it. Separate cold and warm startup, control benchmark conditions, and keep security or data-integrity initialization on the correct path.'),
  card(189, 'engineering', 'A release-only crash appears after enabling shrinking. How would you debug it?',
    'Reproduce with the same release configuration, retrace obfuscated stacks using the matching mapping file, and inspect reflection, serialization, JNI, or generated entry points that shrinking cannot infer. Add the narrowest justified keep rule or fix metadata generation. Test the minified artifact in CI instead of relying only on debug builds.',
    'R8 consumes ProGuard-style rules, so old rule files remain relevant during migration. Broad keep-everything rules hide the cause and lose optimization; preserve mapping files per released artifact.'),
  card(194, 'engineering', 'How would you protect credentials and local data in a mobile app?',
    'Assume anything shipped in an APK or JavaScript bundle can be extracted. Keep privileged secrets on a server, minimize retained tokens and personal data, and use Android Keystore for appropriate device-bound cryptographic keys. Design encryption, authentication, backup, logging, and logout cleanup together against a concrete threat model.',
    'Keystore does not store arbitrary large application data or make a compromised device trustworthy. Never log tokens; consider recovery and key invalidation so encrypted data does not become silently unusable.'),
  card(198, 'engineering', 'How would you review an exported component and its deep-link inputs?',
    'Decide explicitly whether external access is needed, restrict it with permissions where appropriate, and validate caller-controlled URIs, extras, and file grants. Authorize the actual data action independently of navigation. Prefer narrowly scoped content URI grants over exposing private filesystem paths, and test malicious callers that bypass the normal UI.',
    'The app sandbox protects private app data but exported entry points intentionally cross it. Package visibility is not an authorization boundary, and a verified domain does not prove the current user owns a record.'),
  card(200, 'engineering', 'How would you detect and mitigate a production regression during a staged rollout?',
    'Track crashes, ANRs, startup and frame health, network and sync outcomes, and domain success rates by release and affected cohort. Attach safe correlation and version context, alert on user impact, and compare against the previous release. Pause rollout or disable the affected feature when needed, then verify recovery before expanding exposure.',
    'Logs must avoid sensitive payloads and have useful retention limits. A remote flag needs a safe cached default and cannot repair every startup crash; plan release rollback or hotfix constraints before the incident.'),
  card(201, "engineering", "How should a senior engineer describe a production incident?",
    "State the user/business impact, detection signal, diagnosis, decision and trade-off, mitigation, verification, and prevention. Separate facts from assumptions and quantify the result when possible.",
    'Explain what evidence changed your hypothesis and why you chose a mitigation under uncertainty. Include a follow-up owner and a measurable prevention check rather than blaming an individual.'),
  card(202, 'architecture', 'How would you paginate a large feed while keeping cached pages available offline?',
    'Use Paging with a Room PagingSource for reads and RemoteMediator to load remote pages into storage. Persist items and remote keys in one transaction, partition keys by query or account, and define refresh and cache-expiry behavior. The UI consumes database-backed paging data and exposes append versus refresh errors separately.',
    'Offset pagination can skip or duplicate rows when the server dataset changes; cursor pagination with stable ordering often fits better. Keep keys consistent with the query, handle deletion and invalidation, and test empty pages and restart recovery.'),
  card(203, 'architecture', 'Several requests receive 401 together. How would you avoid a token-refresh storm?',
    'Coordinate refresh through one owner and serialize or share the refresh operation. Recheck the current token after acquiring coordination because another request may already have refreshed it. Retry an eligible original request at most once with the new token, exclude the refresh endpoint from recursive authentication, and clear session state on permanent refresh rejection.',
    'Respect logout and account changes while refresh is in flight so an old result cannot resurrect a session. Avoid blocking Main, logging credentials, or retrying non-replayable bodies without an explicit policy.'),
  card(204, 'architecture', 'How would you design a chat client for intermittent connectivity and duplicate messages?',
    'Clarify ordering, delivery, and history requirements first. Store messages locally with stable client operation IDs and pending, sent, or failed status. Reconcile server IDs and sequence cursors, deduplicate delivery, page history, and resume from a checkpoint after reconnect. Separate transport connectivity from message acceptance and user-visible delivery state.',
    'A socket is not durable delivery. Choose server ordering guarantees, gap recovery, retention, encryption, and pagination explicitly. Bound memory and background activity; measure send latency, sync lag, and reconciliation failures.'),
  card(205, 'engineering', 'How would you expose an Android capability to React Native using the current native module architecture?',
    'Define a typed TurboModule contract, run Codegen, and implement the generated Android boundary. Validate JS inputs, map failures into a stable error contract, and make expensive operations asynchronous. Keep Activity-dependent work behind lifecycle checks, clean up resources when the module is invalidated, and test both the JS contract and native behavior.',
    'Do not assume a native call is off the UI thread or that a React Native instance lives for the entire process. Maintain an adapter when migrating a legacy bridge module; avoid high-frequency cross-runtime traffic when native batching can reduce overhead.'),
  card(206, 'engineering', 'A React Native screen freezes while native Android scrolling stays smooth. How would you investigate?',
    'Profile JS and UI-thread timelines separately in a release build. Look for heavy JS rendering, synchronous native calls, oversized payloads, and expensive native view work. Reduce avoidable renders, virtualize long lists, batch boundary traffic, and move suitable computation off the critical thread. Verify with a representative user journey rather than only debug performance.',
    'JS stalls, UI-thread stalls, and memory pressure need different fixes. The new architecture reduces some boundary costs but does not make synchronous work free or remove the need for lifecycle-safe native integration.'),
];

const examples: Record<string, NonNullable<FlashcardText['code']>> = {
  'fc-065': kotlin('JUnit test with kotlinx-coroutines-test and Flow; imports: Test, assertEquals, ExperimentalCoroutinesApi, debounce, first, flow, runTest. Virtual time skips delay.', `@OptIn(ExperimentalCoroutinesApi::class)
@Test
fun latestQueryWins() = runTest {
    val queries = flow {
        emit("a")
        kotlinx.coroutines.delay(100)
        emit("android")
    }
    assertEquals("android", queries.debounce(300).first())
}`)!,
  'fc-078': kotlin('Inside a ViewModel; queries is Flow<String>, repository.search returns Flow<List<Item>>. Imports: ExperimentalCoroutinesApi, FlowPreview, debounce, distinctUntilChanged, flatMapLatest, map.', `@OptIn(FlowPreview::class, ExperimentalCoroutinesApi::class)
val results = queries
    .map { it.trim() }
    .debounce(300)
    .distinctUntilChanged()
    .flatMapLatest { query -> repository.search(query) }`)!,
  'fc-096': kotlin('In Fragment.onCreateView; imports: ComposeView and ViewCompositionStrategy. CheckoutScreen reads the shared ViewModel at the screen boundary.', `return ComposeView(requireContext()).apply {
    setViewCompositionStrategy(
        ViewCompositionStrategy.DisposeOnViewTreeLifecycleDestroyed
    )
    setContent { CheckoutScreen() }
}`)!,
  'fc-126': kotlin('Inside a composable; requestId identifies work, onFinished is a callback. Imports: LaunchedEffect, rememberUpdatedState, getValue.', `val latestOnFinished by rememberUpdatedState(onFinished)
LaunchedEffect(requestId) {
    repository.load(requestId)
    latestOnFinished()
}`)!,
  'fc-133': kotlin('Inside an Android composable; dependency: lifecycle-runtime-compose. Imports: collectAsStateWithLifecycle and getValue.', `val state by viewModel.state.collectAsStateWithLifecycle()
FeedScreen(state = state, onRefresh = viewModel::refresh)`)!,
  'fc-160': kotlin('Inside a repository; db is RoomDatabase, DAOs accept the mapped entities. Imports: androidx.room.withTransaction. Network work finishes before the transaction.', `suspend fun refresh() {
    val page = api.fetchFirstPage()
    db.withTransaction {
        itemDao.replaceForQuery(queryId, page.items)
        keyDao.save(queryId, page.nextCursor)
    }
}`)!,
  'fc-205': {
    language: 'typescript',
    context: 'NativeBattery.ts: Codegen spec for a TurboModule named NativeBattery. React Native Codegen configuration and the generated Android implementation are required.',
    code: `import type {TurboModule} from 'react-native';
import {TurboModuleRegistry} from 'react-native';

export interface Spec extends TurboModule {
  getLevel(): Promise<number>;
}

export default TurboModuleRegistry.getEnforcing<Spec>('NativeBattery');`,
  },
};
export const interviewCards: readonly FlashcardText[] = reviewedCards.map(card => ({
  ...card, ...(examples[card.id] ? { code: examples[card.id] } : {}),
}));
